const board = $input.first().json;
const issues = [];

for (const pipeline of board.pipelines) {
  for (const issue of pipeline.issues) {
    issues.push({
      json: {
        issueNumber: issue.issue_number,
        pipeline: pipeline.name,
        estimate: issue.estimate ? issue.estimate.value : null,
        isEpic: issue.is_epic
      }
    });
  }
}

return issues;
